usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Projects.Users.Get(context.TODO(), "project_id", "user_id")
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
